const getMissionBudgetUsage = `-- name: GetMissionBudgetUsage :one
WITH per_run AS (
    SELECT
        run.id,
        run.status,
        node.budget_estimate_tokens,
        node.budget_estimate_cost_usd_ticks,
        COALESCE(SUM(
            COALESCE(usage.input_tokens, 0)
            + COALESCE(usage.output_tokens, 0)
            + COALESCE(usage.cache_read_tokens, 0)
            + COALESCE(usage.cache_write_tokens, 0)
        ), 0)::bigint AS actual_tokens,
        COALESCE(SUM(usage.cost_usd_ticks) FILTER (WHERE usage.cost_usd_ticks IS NOT NULL), 0)::bigint AS actual_cost_usd_ticks,
        COUNT(usage.task_id)::bigint AS usage_rows,
        COUNT(usage.cost_usd_ticks) FILTER (WHERE usage.cost_usd_ticks IS NOT NULL)::bigint AS authoritative_cost_rows
    FROM orchestration_run run
    JOIN task_node node
      ON node.issue_id = run.task_node_id
     AND node.workspace_id = run.workspace_id
     AND node.mission_id = run.mission_id
    LEFT JOIN agent_task_queue task
      ON task.orchestration_run_id = run.id
    LEFT JOIN task_usage usage
      ON usage.task_id = task.id
    WHERE run.workspace_id = $1
      AND run.mission_id = $2
    GROUP BY run.id, run.status, node.budget_estimate_tokens, node.budget_estimate_cost_usd_ticks
)
SELECT
    COALESCE(SUM(CASE
        WHEN status NOT IN ('queued', 'dispatched', 'running') AND usage_rows = 0
            THEN budget_estimate_tokens
        ELSE actual_tokens
    END), 0)::bigint AS consumed_tokens,
    COALESCE(SUM(CASE
        WHEN status IN ('queued', 'dispatched', 'running')
            THEN GREATEST(budget_estimate_tokens - actual_tokens, 0)
        ELSE 0
    END), 0)::bigint AS reserved_tokens,
    COALESCE(SUM(CASE
        WHEN status NOT IN ('queued', 'dispatched', 'running') AND authoritative_cost_rows = 0
            THEN budget_estimate_cost_usd_ticks
        ELSE actual_cost_usd_ticks
    END), 0)::bigint AS consumed_cost_usd_ticks,
    COALESCE(SUM(CASE
        WHEN status IN ('queued', 'dispatched', 'running')
            THEN GREATEST(budget_estimate_cost_usd_ticks - actual_cost_usd_ticks, 0)
        ELSE 0
    END), 0)::bigint AS reserved_cost_usd_ticks
FROM per_run
`

type GetMissionBudgetUsageParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	MissionID   pgtype.UUID `json:"mission_id"`
}

type GetMissionBudgetUsageRow struct {
	ConsumedTokens       int64 `json:"consumed_tokens"`
	ReservedTokens       int64 `json:"reserved_tokens"`
	ConsumedCostUsdTicks int64 `json:"consumed_cost_usd_ticks"`
	ReservedCostUsdTicks int64 `json:"reserved_cost_usd_ticks"`
}

func (q *Queries) GetMissionBudgetUsage(ctx context.Context, arg GetMissionBudgetUsageParams) (GetMissionBudgetUsageRow, error) {
	row := q.db.QueryRow(ctx, getMissionBudgetUsage, arg.WorkspaceID, arg.MissionID)
	var i GetMissionBudgetUsageRow
	err := row.Scan(
		&i.ConsumedTokens,
		&i.ReservedTokens,
		&i.ConsumedCostUsdTicks,
		&i.ReservedCostUsdTicks,
	)
	return i, err
}

