const revokeMissionAssignments = `-- name: RevokeMissionAssignments :many
UPDATE orchestration_assignment
SET status = 'revoked',
    ended_at = now()
WHERE workspace_id = $1
  AND mission_id = $2
  AND status = 'active'
RETURNING id, workspace_id, mission_id, task_node_id, role, agent_id, runtime_id, status, sequence, supersedes_id, created_by, created_at, ended_at
`

type RevokeMissionAssignmentsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	MissionID   pgtype.UUID `json:"mission_id"`
}

func (q *Queries) RevokeMissionAssignments(ctx context.Context, arg RevokeMissionAssignmentsParams) ([]OrchestrationAssignment, error) {
	rows, err := q.db.Query(ctx, revokeMissionAssignments, arg.WorkspaceID, arg.MissionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OrchestrationAssignment{}
	for rows.Next() {
		var i OrchestrationAssignment
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.MissionID,
			&i.TaskNodeID,
			&i.Role,
			&i.AgentID,
			&i.RuntimeID,
			&i.Status,
			&i.Sequence,
			&i.SupersedesID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.EndedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

